const portalTranslate=(text,lang)=>PORTAL_TEXT[normalizeLang(lang)]?.[text]||text;
const applyPortalTranslation=(lang)=>{
 const root=document.getElementById('root'); if(!root)return;
 const walk=()=>{
  const dict=PORTAL_TEXT[normalizeLang(lang)]||{};
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT); let n;
  while(n=walker.nextNode()){ const raw=n.nodeValue; const trimmed=raw.trim(); if(!trimmed) continue; let out=dict[trimmed]||trimmed; out=out.replace(/^Hello, /,dict['Hello,']?dict['Hello,']+' ':'Hello, '); out=out.replace(/^Application ID: /,dict['Application ID:']?dict['Application ID:']+' ':'Application ID: '); out=out.replace(/^Tracking ID: /,dict['Tracking ID:']?dict['Tracking ID:']+' ':'Tracking ID: '); if(out!==trimmed)n.nodeValue=raw.replace(trimmed,out); }
  root.querySelectorAll('input[placeholder],textarea[placeholder],button[title],a[title]').forEach(el=>{const attr=el.hasAttribute('placeholder')?'placeholder':'title'; const val=el.getAttribute(attr); if(dict[val])el.setAttribute(attr,dict[val]);});
 };
 walk();
 if(window.__sevaTranslationObserver) window.__sevaTranslationObserver.disconnect();
 window.__sevaTranslationObserver=new MutationObserver(()=>walk());
 window.__sevaTranslationObserver.observe(root,{childList:true,subtree:true,characterData:true});
};

