function App(){
 const [auth,setAuth]=useState(()=>localStorage.getItem('sevasetu_token')?'ok':'welcome');
 const [currentUser,setCurrentUser]=useState(()=>{try{return JSON.parse(localStorage.getItem('sevasetu_user')||'null')}catch{return null}});
 const [page,setPage]=useState('Home');
 const [lang,setLangRaw]=useState(normalizeLang(localStorage.getItem('sevasetu_lang')||'English'));
 const setLang=v=>setLangRaw(normalizeLang(v));
 useEffect(()=>{localStorage.setItem('sevasetu_lang',lang); document.documentElement.lang=langCode(lang); applyPortalTranslation(lang)},[lang]);
 useEffect(()=>{const token=localStorage.getItem('sevasetu_token'); if(!token)return; fetch(API+'/me',{headers:{Authorization:'Bearer '+token}}).then(r=>r.ok?r.json():Promise.reject()).then(j=>{if(j.user){setCurrentUser(j.user);localStorage.setItem('sevasetu_user',JSON.stringify(j.user));}}).catch(()=>{});},[]);
 const [q,setQ]=useState('');
 const [chat,setChat]=useState(''),[menu,setMenu]=useState(false),[easy,setEasy]=useState(false),[show,setShow]=useState(false),[modal,setModal]=useState(null);
 const [langNotice,setLangNotice]=useState(false);
 const [apps,setApps]=useState(()=>JSON.parse(localStorage.getItem('sevasetu_apps')||'null')||[
  {name:'Income Certificate',id:'SV-2026-1042',status:'Under Review',date:'28 Sep 2026'},
  {name:'Ration Card',id:'SV-2026-0981',status:'Approved',date:'24 Sep 2026'},
  {name:'Caste Certificate',id:'SV-2026-0874',status:'In Progress',date:'18 Sep 2026'}]);
 const [docs,setDocs]=useState(()=>JSON.parse(localStorage.getItem('sevasetu_docs')||'null')||[
  {name:'Aadhaar Card',type:'Identity',sample:true},{name:'Income Certificate',type:'Certificate',sample:true},{name:'Caste Certificate',type:'Certificate',sample:true}]);
 const [profile,setProfile]=useState(()=>{try{return JSON.parse(localStorage.getItem('sevasetu_profile')||'null')||null}catch{return null}});
 useEffect(()=>{if(currentUser){setProfile(p=>({...({name:'',mobile:'',email:'',state:'Madhya Pradesh'}),...(p||{}),name:currentUser.name||p?.name||'',mobile:currentUser.mobile||p?.mobile||'',email:currentUser.email||p?.email||''}));}},[currentUser]);
 useEffect(()=>{if(profile) localStorage.setItem('sevasetu_profile',JSON.stringify(profile))},[profile]);
 const [notifications,setNotifications]=useState(()=>JSON.parse(localStorage.getItem('sevasetu_notifications')||'null')||[
  {title:'Application update',text:'Your Ration Card application was approved.',time:'2 hours ago',read:false},
  {title:'Document reminder',text:'Review required documents for your certificate.',time:'Yesterday',read:false},
  {title:'Service announcement',text:'New citizen services are available to explore.',time:'3 days ago',read:true}]);
 const [msgs,setMsgs]=useState([{by:'ai',text:'Namaste! I am SEVA AI. Ask me to find a service, scheme, document or application status.'}]);
 const unread=notifications.filter(n=>!n.read).length;
 useEffect(()=>localStorage.setItem('sevasetu_apps',JSON.stringify(apps)),[apps]);
 useEffect(()=>localStorage.setItem('sevasetu_docs',JSON.stringify(docs)),[docs]);
 useEffect(()=>localStorage.setItem('sevasetu_notifications',JSON.stringify(notifications)),[notifications]);
 const speak=t=>{if(window.speechSynthesis){window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang=langCode(lang);window.speechSynthesis.speak(u)}};
 const voice=()=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){alert('Voice input works best in Chrome.');return}const r=new SR();r.lang=langCode(lang);r.interimResults=false;r.onresult=e=>{const v=e.results[0][0].transcript;setChat(v);ask(v)};r.start()};
 const go=p=>{setPage(p);setMenu(false);setModal(null)};
 const ask=(v=chat)=>{if(!v.trim())return;setMsgs(m=>[...m,{by:'user',text:v}]);const t=v.toLowerCase();let ans='I can open services, schemes, documents, applications, notifications, profile and settings.';
  if(/track|status|application|आवेदन/.test(t)){go('Applications');ans='Opening Application Tracking.'}
  else if(/document|vault|aadhaar|pan|दस्तावेज/.test(t)){go('Document Vault');ans='Opening your Document Vault.'}
  else if(/scheme|yojana|scholarship|योजना/.test(t)){go('Schemes');ans='Opening Government Schemes.'}
  else if(/certificate|service|income|caste|domicile|सेवा|प्रमाण/.test(t)){go('Services');ans='Opening Government Services.'}
  else if(/notification|alert|सूचना/.test(t)){go('Notifications');ans='Opening Notifications.'}
  else if(/profile|account|प्रोफाइल/.test(t)){go('Profile');ans='Opening your Profile.'}
  else if(/setting|language|accessibility|सेटिंग/.test(t)){go('Settings');ans='Opening Settings and Accessibility.'}
  else if(/home|dashboard|मुख्य/.test(t)){go('Home');ans='Opening your citizen dashboard.'}
  else {const found=services.find(s=>t.includes(s[0].split(' ')[0].toLowerCase()));if(found){go('Services');setQ(found[0]);ans=`I found ${found[0]}. Select it to view details.`}}
  setMsgs(m=>[...m,{by:'ai',text:ans}]);setChat('')};
 const apply=service=>setModal({type:'service',data:Array.isArray(service)?service:services.find(s=>s[0]===service)});
 const submit=async()=>{const name=modal?.data?.[0];if(!name)return;let created={name,id:'SV-'+Math.floor(100000+Math.random()*899999),status:'Submitted',date:new Date().toLocaleDateString('en-IN')};
  const token=localStorage.getItem('sevasetu_token'); if(token){try{const r=await fetch(API+'/applications',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify({service:name})});if(r.ok){const j=await r.json();created={name,id:j.application?.trackingId||created.id,status:j.application?.status||'Submitted',date:new Date(j.application?.createdAt||Date.now()).toLocaleDateString('en-IN')}}}catch{}}
  setApps(a=>[created,...a]);setNotifications(n=>[{title:'Application submitted',text:`${name} application was submitted successfully.`,time:'Just now',read:false},...n]);setModal(null);go('Applications')};
 if(auth!=='ok') return <Auth auth={auth} setAuth={setAuth} lang={lang} setLang={setLang} show={show} setShow={setShow} onUser={u=>{setCurrentUser(u);localStorage.setItem('sevasetu_user',JSON.stringify(u));}}/>;
 return <div className={'app '+(easy?'easy':'')}>
  <aside className={menu?'sidebar open':'sidebar'}><div className="brand"><img src={logo}/><div><b>SEVASETU</b><small>सरकार से आप तक</small></div><button className="close" onClick={()=>setMenu(false)}><X/></button></div><div className="navlabel">{tr(lang,'mainMenu')}</div>
   {nav.map(([n,I])=><button key={n} className={'nav '+(page===n?'active':'')} onClick={()=>go(n)}><I/><span>{tr(lang,n==='Home'?'home':n==='Services'?'services':n==='Schemes'?'schemes':n==='Document Vault'?'documents':n==='Applications'?'applications':n==='Notifications'?'notifications':n==='Profile'?'profile':n==='Settings'?'settings':'ai')}</span>{n==='Notifications'&&unread>0&&<b className="badge">{unread}</b>}</button>)}
   <div className="sidebottom"><div className="help"><b>Need help?</b><p>SEVA AI is here to guide you.</p><button onClick={()=>go('SEVA AI')}>Ask SEVA AI →</button></div><div className="user"><div className="avatar">{(profile?.name||'G').charAt(0).toUpperCase()}</div><div><b>{profile?.name||'Guest Citizen'}</b><small>Citizen Account</small></div><button onClick={()=>{localStorage.removeItem('sevasetu_token');localStorage.removeItem('sevasetu_user');setCurrentUser(null);setProfile(null);setAuth('welcome')}}><LogOut/></button></div></div>
  </aside>{menu&&<div className="scrim" onClick={()=>setMenu(false)}/>}<main><header><button className="hamb" onClick={()=>setMenu(!menu)}><Menu/></button><div className="crumb">SEVASETU　›　<b>{page}</b></div><div className="actions"><label className="topsearch"><Search/><input placeholder={tr(lang,'search')} value={q} onChange={e=>{setQ(e.target.value);go('Services')}}/></label><select value={lang} onChange={e=>setLang(e.target.value)}>{langOptions()}</select><button className="icon" onClick={()=>go('Notifications')}><Bell/>{unread>0&&<i/>}</button><button className="profile" onClick={()=>go('Profile')}>{(profile?.name||'G').charAt(0).toUpperCase()}</button></div></header>
  <div className="content">{langNotice&&<div className="langnotice"><Languages/><b>{LANGS.find(x=>x.value===lang)?.label}</b><span>{tr(lang,'languageChanged')}</span></div>}
   {page==='Home'&&<HomePage apps={apps} easy={easy} setEasy={setEasy} go={go} apply={apply} />}
   {page==='Services'&&<ServicesPage q={q} setQ={setQ} apply={apply}/>} 
   {page==='Schemes'&&<SchemesPage q={q} setQ={setQ} setModal={setModal}/>} 
   {page==='Document Vault'&&<Documents docs={docs} setDocs={setDocs} speak={speak}/>} 
   {page==='Applications'&&<Applications apps={apps} setModal={setModal}/>} 
   {page==='SEVA AI'&&<AI msgs={msgs} chat={chat} setChat={setChat} ask={ask} voice={voice} speak={speak}/>} 
   {page==='Notifications'&&<Notifications notifications={notifications} setNotifications={setNotifications}/>} 
   {page==='Profile'&&<Profile profile={profile} setProfile={setProfile}/>} 
   {page==='Settings'&&<SettingsPage lang={lang} setLang={setLang} easy={easy} setEasy={setEasy} speak={speak} voice={voice}/>} 
   <footer><div><img src={logo}/> <b>SEVASETU <small>सरकार से आप तक</small></b></div><span>Empowering Citizens • Simplifying Governance</span><a href="https://web.umang.gov.in/" target="_blank" rel="noreferrer">Explore UMANG ↗</a></footer>
  </div></main>
  {modal&&<Modal modal={modal} close={()=>setModal(null)} submit={submit} speak={speak}/>} {easy&&<div className="easybadge"><Accessibility/> Easy Access Mode <button onClick={()=>setEasy(false)}><X/></button></div>}
 </div>
}

function Auth({auth,setAuth,lang,setLang,show,setShow,onUser}){const [mobile,setMobile]=useState('');const [name,setName]=useState('');const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [otp,setOtp]=useState('');const [loading,setLoading]=useState(false);const [msg,setMsg]=useState('');const [err,setErr]=useState('');
 const [reset,setReset]=useState('');
 const submit=async e=>{e.preventDefault();setLoading(true);setErr('');setMsg('');try{
   if(auth==='login'){const r=await fetch(API+'/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mobile,password})});const j=await r.json();if(!r.ok)throw Error(j.error);localStorage.setItem('sevasetu_token',j.token);if(j.user)onUser(j.user);setAuth('ok');return}
   if(auth==='register'){const r=await fetch(API+'/auth/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,mobile,email,password})});const j=await r.json();if(!r.ok)throw Error(j.error);setMsg('Registration created. Demo OTP is printed in the server console.');setAuth('verify');return}
   if(auth==='forgot'){const r=await fetch(API+'/auth/request-otp',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mobile,purpose:'reset'})});const j=await r.json();if(!r.ok)throw Error(j.error);setMsg('Reset OTP generated. Check the server console in demo mode.');setAuth('reset');return}
   if(auth==='verify'){const r=await fetch(API+'/auth/verify-otp',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mobile,otp})});const j=await r.json();if(!r.ok)throw Error(j.error);localStorage.setItem('sevasetu_token',j.token);if(j.user)onUser(j.user);setAuth('ok');return}
   if(auth==='reset'){const r=await fetch(API+'/auth/reset-password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mobile,otp,newPassword:reset})});const j=await r.json();if(!r.ok)throw Error(j.error);setMsg('Password reset successfully. You can now login.');setAuth('login');return}
 }catch(e){setErr(e.message||'Backend unavailable. Start the server with npm run dev.')}finally{setLoading(false)}};
 return <div className="auth"><section className="art"><img src={logo}/><h1>SEVASETU</h1><h2>सरकार से आप तक</h2><h3>Your Government Services,<br/>Now Just a Click Away</h3><p>Access public services, discover schemes, manage documents and track applications — all in one place.</p><div className="pills">Simple　•　Smart　•　Accessible</div><small>Madhya Pradesh • Citizen Services</small></section><section className="authright"><div className="authbar"><select value={lang} onChange={e=>setLang(e.target.value)}>{langOptions()}</select><a href="https://web.umang.gov.in/" target="_blank" rel="noreferrer">Explore public services ↗</a></div><div className="authbox"><img src={logo}/><h2>{auth==='welcome'?tr(lang,'welcome'):auth==='login'?tr(lang,'login'):auth==='register'?tr(lang,'create'):auth==='forgot'?tr(lang,'forgot'):auth==='verify'?tr(lang,'verify'):tr(lang,'reset')}</h2><p>{auth==='welcome'?'Government services made simple, smart and accessible.':auth==='login'?'Sign in to your citizen dashboard.':auth==='register'?'Create an account to manage services.':auth==='forgot'?'Enter your mobile number to receive a secure reset code.':auth==='verify'?'Enter the OTP sent to your mobile.':'Enter a new password for your account.'}</p>
 {msg&&<div className="banner"><CheckCircle2/><span>{msg}</span></div>}{err&&<div className="banner error"><AlertCircle/><span>{err}</span></div>}
 {auth==='welcome'?<><button className="primary full" onClick={()=>setAuth('login')}><LogIn/> {tr(lang,'login')}</button><button className="outline full" onClick={()=>setAuth('register')}><UserPlus/> {tr(lang,'register')}</button><button className="link" onClick={()=>{const u={name:'Guest Citizen',mobile:'',email:'',state:'Madhya Pradesh'};onUser(u);setAuth('ok')}}>Continue as Guest →</button></>:<form onSubmit={submit}>{auth==='register'&&<><label>Full Name</label><input value={name} onChange={e=>setName(e.target.value)} required placeholder="Enter full name"/><label>Email (optional)</label><input value={email} onChange={e=>setEmail(e.target.value)} type="email" placeholder="name@example.com"/></>}<label>Mobile Number</label><input value={mobile} onChange={e=>setMobile(e.target.value.replace(/\D/g,'').slice(0,10))} required placeholder="10-digit mobile number" inputMode="numeric"/>{['verify','reset'].includes(auth)&&<><label>OTP</label><input value={otp} onChange={e=>setOtp(e.target.value.replace(/\D/g,'').slice(0,6))} required placeholder="6-digit OTP" maxLength="6"/></>}{auth==='reset'?<><label>New Password</label><input value={reset} onChange={e=>setReset(e.target.value)} type="password" minLength="8" required placeholder="At least 8 characters"/></>:auth!=='forgot'&&auth!=='verify'&&<><label>Password</label><div className="pass"><input value={password} onChange={e=>setPassword(e.target.value)} type={show?'text':'password'} minLength="8" required placeholder="At least 8 characters"/><button type="button" onClick={()=>setShow(!show)}>{show?<EyeOff/>:<Eye/>}</button></div></>}{auth==='login'&&<button type="button" className="link forgot" onClick={()=>setAuth('forgot')}>{tr(lang,'forgot')}</button>}<button className="primary full" disabled={loading}>{loading?'Please wait…':auth==='forgot'?'Send Reset OTP':auth==='register'?'Register & Verify OTP':auth==='verify'?'Verify & Continue':auth==='reset'?'Save New Password':'Login Securely'}</button><p className="switch">{auth==='login'?'New user?':auth==='register'?'Already have an account?':'Back to sign in'} <button type="button" onClick={()=>setAuth('login')}>Login</button></p></form>}
 <div className="secure"><ShieldCheck/> Your information is protected in this demo experience.</div></div><footer>© 2026 SEVASETU • Sarkar Se Aap Tak</footer></section></div>}

function HomePage({apps,easy,setEasy,go,apply}){return <><div className="welcome"><div><small className="eyebrow">CITIZEN DASHBOARD</small><h1>Hello, {profile?.name||'Citizen'} 👋</h1><p>Welcome to SEVASETU — your one-stop citizen services portal.</p></div><button className="outline" onClick={()=>setEasy(!easy)}><Accessibility/> {easy?'Exit Easy Access':'Easy Access Mode'}</button></div><div className="hero"><small>✦ YOUR SERVICES, SIMPLIFIED</small><h2>Government Services<br/><em>Made Simple for You!</em></h2><p>Discover services, check eligibility and manage applications from one place.</p><button onClick={()=>go('Services')}>Explore Services <ArrowRight/></button><Landmark className="hero-land"/></div><div className="stats">{[['Total Applications',apps.length,ClipboardList],['Completed',apps.filter(a=>a.status==='Approved').length,CheckCircle2],['In Progress',apps.filter(a=>a.status!=='Approved').length,Clock3]].map(([n,v,I])=><div className="stat" key={n}><I/><div><small>{n}</small><b>{v}</b><small>Across your services</small></div></div>)}</div><Section title="Quick Services" action={()=>go('Services')}/><div className="servicegrid">{services.slice(0,4).map(s=><Service key={s[0]} s={s} onClick={()=>apply(s[0])}/>)}</div><div className="columns"><div className="panel"><Section title="Recent Applications" action={()=>go('Applications')}/>{apps.slice(0,3).map(a=><AppRow key={a.id} a={a}/>)}</div><div className="aipromo"><div className="bot"><MessageCircle/></div><small>MEET YOUR DIGITAL ASSISTANT</small><h2>SEVA AI Assistant</h2><p>Ask questions, find services or navigate using voice or text.</p><button onClick={()=>go('SEVA AI')}>Chat with SEVA AI →</button></div></div><Section title="Popular Schemes" action={()=>go('Schemes')}/><div className="schemes">{schemes.slice(0,3).map(s=><Scheme key={s[0]} s={s}/>)}</div></>}
function ServicesPage({q,setQ,apply}){const list=services.filter(s=>s.join(' ').toLowerCase().includes(q.toLowerCase()));return <><Title t="Government Services" s="Find and access citizen services from one place."/><div className="filter"><Search/><input placeholder={tr(lang,'search')} value={q} onChange={e=>setQ(e.target.value)}/></div><div className="servicegrid all">{list.map(s=><Service key={s[0]} s={s} onClick={()=>apply(s)}/>)}</div>{!list.length&&<Empty text="No service found. Try income, caste, ration or land."/>}</>}
function SchemesPage({q,setQ,setModal}){const list=schemes.filter(s=>s.join(' ').toLowerCase().includes(q.toLowerCase()));return <><Title t="Government Schemes" s="Explore public welfare programs and scheme information."/><div className="filter"><Search/><input placeholder="Search schemes..." value={q} onChange={e=>setQ(e.target.value)}/></div><div className="schemes">{list.map(s=><Scheme key={s[0]} s={s} onClick={()=>setModal({type:'scheme',data:s})}/>)}</div></>}
function Documents({docs,setDocs,speak}){const upload=e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>5*1024*1024){alert('Maximum demo file size is 5 MB.');return}const url=URL.createObjectURL(f);setDocs(d=>[...d,{name:f.name,type:f.type.includes('pdf')?'PDF':'Image',url,size:Math.ceil(f.size/1024)+' KB'}]);e.target.value=''};const view=d=>{if(d.url)window.open(d.url,'_blank');else alert('This sample document has no real file attached.')};const read=d=>speak(`${d.name}. ${d.type}. ${d.size||'Sample document'}.`);return <><Title t="Document Vault" s="Store, view, download and read important documents."/><div className="banner"><ShieldCheck/><div><b>Your documents, in one place</b><p>Demo documents are stored in this browser session. Official DigiLocker integration is not connected.</p></div></div><label className="upload"><Upload/><b>Upload a document</b><small>PDF, JPG or PNG • Maximum 5 MB</small><input type="file" accept=".pdf,.jpg,.jpeg,.png" onChange={upload}/></label><div className="docgrid">{docs.map((d,i)=><div className="doc" key={d.name+i}><FileText/><div><b>{d.name}</b><small>{d.type}{d.size?' • '+d.size:''}</small></div><div className="docactions"><button title="View" onClick={()=>view(d)}><ExternalLink/></button><button title="Read aloud" onClick={()=>read(d)}><Volume2/></button>{d.url&&<a title="Download" href={d.url} download={d.name}><Download/></a>}<button title="Remove" onClick={()=>setDocs(x=>x.filter((_,j)=>j!==i))}><Trash2/></button></div></div>)}</div></>}
function Applications({apps,setModal}){return <><Title t="My Applications" s="Track status and updates for your service requests."/><div className="panel app-list">{apps.map(a=><AppRow key={a.id} a={a} detailed onDetails={()=>setModal({type:'application',data:a})}/>)}</div></>}
function AI({msgs,chat,setChat,ask,voice,speak}){return <><Title t="SEVA AI Assistant" s="Speak or type a request to find services and navigate the portal."/><div className="chatlayout"><div className="chatbox"><div className="chathead"><div className="bot"><MessageCircle/></div><div><b>SEVA AI</b><small>● Ready to help</small></div><button className="icon" onClick={()=>speak(msgs.at(-1).text)}><Volume2/></button></div><div className="messages">{msgs.map((m,i)=><div className={'message '+m.by} key={i}><p>{m.text}</p>{m.by==='ai'&&<button onClick={()=>speak(m.text)}><Volume2/> Read aloud</button>}</div>)}</div><div className="suggest">{['Find a certificate','Track my application','Show schemes','Open document vault'].map(s=><button key={s} onClick={()=>ask(s)}>{s}</button>)}</div><div className="chatinput"><button onClick={voice}><Mic/></button><input value={chat} onChange={e=>setChat(e.target.value)} onKeyDown={e=>e.key==='Enter'&&ask()} placeholder="Type or speak your question..."/><button onClick={()=>ask()}><Send/></button></div></div><aside className="try"><b>✦ Try asking</b>{['I need an income certificate','How can I check my application?','Show government schemes','Where are my documents?'].map(s=><button key={s} onClick={()=>ask(s)}>{s}　›</button>)}<div className="voice"><Mic/><b>Hands-free help</b><p>Speak naturally using a supported browser.</p><button onClick={voice}>Start voice input</button></div></aside></div></>}
function Notifications({notifications,setNotifications}){return <><Title t="Notifications" s="Updates and messages about citizen services."/><div className="panel"><div className="notice-actions"><button className="outline" onClick={()=>setNotifications(n=>n.map(x=>({...x,read:true})))}>Mark all read</button><button className="outline" onClick={()=>setNotifications([])}>Clear all</button></div>{notifications.map((n,i)=><div className={'notice '+(n.read?'read':'')} key={i} onClick={()=>setNotifications(x=>x.map((z,j)=>j===i?{...z,read:true}:z))}><Bell/><div><b>{n.title}</b><p>{n.text}</p><small>{n.time}</small></div>{!n.read&&<span className="dot"/>}</div>)}{!notifications.length&&<Empty text="No notifications."/>}</div></>}
function Profile({profile,setProfile}){const save=()=>{alert('Profile saved for this session.')};return <><Title t="My Profile" s="Manage your citizen profile and preferences."/><div className="panel profilebox"><div className="bigavatar">A</div><h2>{profile.name}</h2><p>Citizen ID: SV-CIT-2026-001</p><div className="fields"><label>Full Name<input value={profile.name} onChange={e=>setProfile({...profile,name:e.target.value})}/></label><label>Mobile Number<input value={profile.mobile} onChange={e=>setProfile({...profile,mobile:e.target.value})}/></label><label>Email Address<input value={profile.email} onChange={e=>setProfile({...profile,email:e.target.value})}/></label><label>State<input value={profile.state} onChange={e=>setProfile({...profile,state:e.target.value})}/></label></div><button className="primary" onClick={save}><Check/> Save Changes</button></div></>}
function SettingsPage({lang,setLang,easy,setEasy,speak,voice}){return <><Title t={tr(lang,'settingsTitle')} s={tr(lang,'chooseLanguage')}/><div className="panel settings"><h3><Languages/> {tr(lang,'portalLanguage')}</h3><div className="setting"><div><b>{tr(lang,'portalLanguage')}</b><p>{tr(lang,'chooseLanguage')}</p></div><select aria-label={tr(lang,'portalLanguage')} value={lang} onChange={e=>setLang(e.target.value)}>{langOptions()}</select></div><h3><Accessibility/> {tr(lang,'accessibility')}</h3><div className="setting"><div><b>{tr(lang,'easyAccess')}</b><p>{tr(lang,'largerControls')}</p></div><input type="checkbox" checked={easy} onChange={e=>setEasy(e.target.checked)}/></div><div className="setting"><div><b>{tr(lang,'tts')}</b><p>{tr(lang,'hearSample')}</p></div><button className="outline" onClick={()=>speak('Welcome to SEVASETU. Sarkar se aap tak.')}><Volume2/> {tr(lang,'testAudio')}</button></div><div className="setting"><div><b>{tr(lang,'voiceInput')}</b><p>{tr(lang,'speakNavigate')}</p></div><button className="outline" onClick={voice}><Mic/> {tr(lang,'tryVoice')}</button></div></div></>}
function Modal({modal,close,submit,speak}){if(modal.type==='scheme'){const s=modal.data;return <div className="overlay" onClick={close}><div className="modal" onClick={e=>e.stopPropagation()}><button className="x" onClick={close}><X/></button><div className="modalicon"><Landmark/></div><small>SCHEME DETAILS</small><h2>{s[0]}</h2><p>{s[2]}</p><div className="infobox"><b>Category</b><p>{s[1]}</p><b>What you can do</b><p>Review the information, check official eligibility and visit the concerned government portal before applying.</p></div><button className="outline full" onClick={()=>speak(`${s[0]}. Category ${s[1]}. ${s[2]}`)}><Volume2/> Read Aloud</button><button className="primary full" onClick={()=>window.open('https://web.umang.gov.in/','_blank')}>Explore Official Services <ExternalLink/></button></div></div>}
 if(modal.type==='application'){const a=modal.data;return <div className="overlay" onClick={close}><div className="modal" onClick={e=>e.stopPropagation()}><button className="x" onClick={close}><X/></button><div className="modalicon"><ClipboardList/></div><small>APPLICATION DETAILS</small><h2>{a.name}</h2><p>Tracking ID: <b>{a.id}</b></p><div className="timeline"><div className="done"><Check/> Submitted</div><div className={a.status!=='Submitted'?'done':''}><Clock3/> Under Review</div><div className={a.status==='Approved'?'done':''}><CheckCircle2/> Completed</div></div><div className="infobox"><b>Current status</b><p>{a.status} • {a.date}</p></div><button className="outline full" onClick={()=>speak(`${a.name}. Application ${a.id}. Current status ${a.status}.`)}><Volume2/> Read Status Aloud</button></div></div>}
 const s=modal.data;return <div className="overlay" onClick={close}><div className="modal" onClick={e=>e.stopPropagation()}><button className="x" onClick={close}><X/></button><div className="modalicon"><ClipboardList/></div><small>SERVICE DETAILS</small><h2>{s[0]}</h2><p>{s[4]}</p><div className="infobox"><b>Before you apply</b><p>• Keep supporting documents ready.<br/>• Review eligibility and details.<br/>• Your demo tracking ID will be generated locally.</p></div><button className="outline full" onClick={()=>speak(`${s[0]}. ${s[4]}`)}><Volume2/> Read Aloud</button><button className="primary full" onClick={submit}>Start Demo Application <ArrowRight/></button></div></div>}
function Title({t,s}){return <div className="title"><small className="eyebrow">CITIZEN PORTAL</small><h1>{t}</h1><p>{s}</p></div>}
function Section({title,action}){return <div className="section"><div><h2>{title}</h2></div><button onClick={action}>View all <ChevronRight/></button></div>}
function Service({s,onClick}){return <button className="service" onClick={onClick}><div className={'svcicon '+s[2]}>{s[3]}</div><div><b>{s[0]}</b><small>{s[1]}</small></div><ChevronRight className="arrow"/></button>}
function Scheme({s,onClick}){return <div className="scheme"><div className="schemesymbol"><Landmark/></div><small>{s[1]}</small><h3>{s[0]}</h3><p>{s[2]}</p><button onClick={onClick||(()=>{})}>View Details →</button></div>}
function AppRow({a,detailed,onDetails}){return <div className="approw"><div className="fileicon"><FileText/></div><div className="appinfo"><b>{a.name}</b><small>Application ID: {a.id}</small></div><span className={'status '+a.status.toLowerCase().replaceAll(' ','-')}>{a.status}</span><small className="date">{a.date}</small>{detailed&&<button onClick={onDetails}>Details ›</button>}</div>}
function Empty({text}){return <div className="panel empty"><Sparkles/><b>{text}</b></div>}
createRoot(document.getElementById('root')).render(<App/>);
